args.sql:
SELECT user_registry, COUNT(*) as cnt FROM (
    SELECT f.user_registry
    FROM fans f
    LEFT JOIN membershipandspending m ON f.user_registry = m.member_fan_pivot
) sub GROUP BY user_registry HAVING COUNT(*) > 1 LIMIT 5;
